[DataEventHandler(tableStr(KCS_KBVRequestTable), DataEventType::Deleted)]
public static void KCS_KBVRequestTable_onDeleted(Common sender, DataEventArgs e)
{
    NDXBVEMailRequestPerCompany nDXBVEMailRequestPerCompany = NDXBVEMailRequestPerCompany::findFromKCS_KBVRequestTable(sender as KCS_KBVRequestTable, true);
    if (nDXBVEMailRequestPerCompany)
    {
        ttsbegin;
        nDXBVEMailRequestPerCompany.KCS_KBVRequestTable = 0;
        nDXBVEMailRequestPerCompany.update();
        ttscommit;

        if (NDXBVEMailRequestControlCenterForm::existInstance())
        {
            NDXBVEMailRequestControlCenterForm formHandler = NDXBVEMailRequestControlCenterForm::getInstance();
            formHandler.reFreshNDXBVEMailRequestPerCompany();
        }
    }
}
